   462	        use simd_json::owned::Object;
   463	        let mut map = Object::new();
   464	        map.insert("component_id".into(), Value::from(info.component_id.clone()));
   465	        map.insert("component_type".into(), Value::from(info.component_type.clone()));
   466	        map.insert("name".into(), Value::from(info.name.clone()));
   467	        map.insert("description".into(), Value::from(info.description.clone()));
