   470	        map.insert("status".into(), Value::from(info.status as i64));
   471	        map.insert("schema_json".into(), Value::from(info.schema_json.clone()));
   472	        let caps: Vec<Value> = info.capabilities.iter().map(|s| Value::from(s.clone())).collect();
   473	        map.insert("capabilities".into(), Value::Array(caps));
