//!
//! Provides a durable, NUMA-aware, BTRFS-integrated registry for all plugins.

use anyhow::{anyhow, Result};
use op_core::state_publisher::StatePublisher;
use op_state::StatePlugin;
use op_state_store::{PluginSchema, SchemaRegistry};
use simd_json::OwnedValue as Value;
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use tokio::process::Command;
use tokio::sync::RwLock;
use tracing::{info, warn};

/// Registry record for a plugin
pub struct PluginRecord {
    pub name: String,
    pub plugin: Arc<RwLock<dyn StatePlugin>>,
    pub storage_path: PathBuf,
    pub change_count: u64,
    pub schema: Option<PluginSchema>,
    pub dbus_path: String,
}

/// Sole authoritative plugin registry
pub struct PluginRegistry {
    plugins: Arc<RwLock<HashMap<String, PluginRecord>>>,
    schema_registry: Arc<RwLock<SchemaRegistry>>,
    base_path: PathBuf,
    publisher: RwLock<Option<Arc<dyn StatePublisher>>>,
    dbus_conn: RwLock<Option<zbus::Connection>>,
}

impl PluginRegistry {
    /// Create a new authoritative registry
    pub fn new(base_path: impl AsRef<Path>, schema_registry: Arc<RwLock<SchemaRegistry>>) -> Self {
        Self {
            plugins: Arc::new(RwLock::new(HashMap::new())),
            schema_registry,
            base_path: base_path.as_ref().to_path_buf(),
            publisher: RwLock::new(None),
            dbus_conn: RwLock::new(None),
        }
    }

    /// Set the state publisher for authoritative updates
    pub async fn set_publisher(&self, publisher: Arc<dyn StatePublisher>) {
        *self.publisher.write().await = Some(publisher);
    }

    /// Set the D-Bus connection for object exportation
    pub async fn set_dbus_connection(&self, conn: zbus::Connection) {
        *self.dbus_conn.write().await = Some(conn);
    }

    /// Register a plugin instance
    pub async fn register(&self, name: String, plugin: Arc<RwLock<dyn StatePlugin>>) -> Result<()> {
        let mut plugins = self.plugins.write().await;

        if plugins.contains_key(&name) {
            return Err(anyhow!("Plugin '{}' already registered", name));
        }

        // Ensure BTRFS subvolume for plugin storage
        let storage_path = self.create_plugin_subvolume(&name).await?;

        let dbus_path = format!("/org/opdbus/v1/plugins/{}", name);

        // Export to D-Bus if connection is available
        if let Some(conn) = &*self.dbus_conn.read().await {
            let host = op_state::dbus_server::PluginDbusHost {
                plugin: plugin.clone(),
            };
            let _ = conn.object_server().at(&dbus_path, host).await;
            info!("Plugin {} exported to D-Bus at {}", name, dbus_path);
        }

        // Extract schema from plugin
        let schema = plugin.read().await.schema();

        // Register schema in SchemaRegistry
        if let Some(s) = &schema {
            self.schema_registry.write().await.register(s.clone());
            info!("Plugin {} schema registered in SchemaRegistry", name);

            // Project schema to SyncEngine immediately so UI can build forms
            if let Some(publ) = &*self.publisher.read().await {
                let _ = publ
                    .publish_change(
                        name.clone(),
                        format!("schema/{}", name),
                        op_core::state_publisher::ChangeType::PropertySet,
                        Some("definition".to_string()),
                        None,
                        s.to_json_schema(),
                        vec!["schema".to_string()],
                        "registry".to_string(),
                    )
                    .await;
                info!("Plugin {} schema projected to SyncEngine", name);
            }
        }

        plugins.insert(
            name.clone(),
            PluginRecord {
                name,
                plugin,
                storage_path,
                change_count: 0,
                schema,
                dbus_path,
            },
        );

        Ok(())
    }

    /// Get a plugin by name
    pub async fn get(&self, name: &str) -> Option<Arc<RwLock<dyn StatePlugin>>> {
        let plugins = self.plugins.read().await;
        plugins.get(name).map(|r| r.plugin.clone())
    }

    async fn create_plugin_subvolume(&self, name: &str) -> Result<PathBuf> {
        let path = self.base_path.join("plugins").join(name);

        if path.exists() {
            return Ok(path);
        }

        tokio::fs::create_dir_all(path.parent().unwrap()).await?;

        let output = Command::new("btrfs")
            .args(["subvolume", "create"])
            .arg(&path)
            .output()
            .await?;

        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            if !stderr.contains("not a btrfs filesystem") {
                warn!(
                    "BTRFS subvolume creation failed: {}. Falling back to directory.",
                    stderr
                );
            }
            tokio::fs::create_dir_all(&path).await?;
        }

        Ok(path)
    }
}
