#!/usr/bin/env python3
import os, sys, json, socket, time, threading
import _dbus_glib_bindings
import dbus, dbus.service, dbus.mainloop.glib

# Initialize gthreads for dbus-python
dbus.mainloop.glib.DBusGMainLoop(set_as_default=True)
_dbus_glib_bindings.gthreads_init()

OVSDB_SOCK = "/var/run/openvswitch/db.sock"
if os.path.exists("/run/openvswitch/db.sock"):
    OVSDB_SOCK = "/run/openvswitch/db.sock"

OPDBUS_BUS_NAME = "org.opdbus"
OPDBUS_PATH_PREFIX = "/org/opdbus/bridge"

def ovsdb_transact(sock_path, *operations):
    request = {"method": "transact", "params": ["Open_vSwitch"] + list(operations), "id": 1}
    raw = json.dumps(request).encode()
    try:
        with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as s:
            s.connect(sock_path)
            s.sendall(raw)
            buf = b""
            while True:
                chunk = s.recv(65536)
                if not chunk:
                    break
                buf += chunk
                try:
                    return json.loads(buf)
                except json.JSONDecodeError:
                    continue
    except Exception as e:
        print(f"OVSDB Error: {e}", file=sys.stderr)
        return {}
    raise RuntimeError("OVSDB socket closed")

def _ovsdb_map(val):
    if isinstance(val, list) and len(val) == 2 and val[0] == "map":
        return dict(val[1])
    return {}

def fetch_bridges():
    op = {"op": "select", "table": "Bridge", "where": [],
          "columns": ["name", "datapath_type", "other_config", "external_ids", "_uuid"]}
    reply = ovsdb_transact(OVSDB_SOCK, op)
    if not reply or "result" not in reply or not reply["result"]:
        return []
    rows = reply["result"][0].get("rows", [])
    return [{"name": row.get("name", ""), "datapath_type": row.get("datapath_type", "system"),
             "uuid": row.get("_uuid", ["uuid", ""])[1],
             "other_config": _ovsdb_map(row.get("other_config")),
             "external_ids": _ovsdb_map(row.get("external_ids"))} for row in rows]

class BridgeObject(dbus.service.Object):
    IFACE = "org.opdbus.Bridge"
    def __init__(self, conn, name, uuid, datapath_type, other_config, external_ids):
        super().__init__(conn, f"{OPDBUS_PATH_PREFIX}/{name}")
        self._name = name
        self._uuid = uuid
        self._datapath_type = datapath_type
        self._other_config = other_config
        self._external_ids = external_ids
        print(f"Found: {name}\n  published /org/opdbus/bridge/{name}", flush=True)

    @dbus.service.method(IFACE, out_signature="s")
    def GetName(self): return self._name
    @dbus.service.method(IFACE, out_signature="s")
    def GetUUID(self): return self._uuid
    @dbus.service.method(IFACE, out_signature="s")
    def GetDatapathType(self): return self._datapath_type
    @dbus.service.method(IFACE, out_signature="a{ss}")
    def GetOtherConfig(self): return dbus.Dictionary(self._other_config, signature="ss")
    @dbus.service.method(IFACE, out_signature="a{ss}")
    def GetExternalIds(self): return dbus.Dictionary(self._external_ids, signature="ss")

def main():
    address = os.environ.get("DBUS_SESSION_BUS_ADDRESS")
    if not address:
        # Fallback to the expected path
        address = "unix:path=/run/op-dbus/session-bus"

    print(f"Connecting to bus at {address}...", flush=True)
    try:
        bus = dbus.bus.BusConnection(address)
    except Exception as e:
        print(f"Connection failed: {e}", file=sys.stderr)
        sys.exit(1)

    name = dbus.service.BusName(OPDBUS_BUS_NAME, bus)

    bridges = fetch_bridges()
    for b in bridges:
        BridgeObject(bus, b['name'], b['uuid'], b['datapath_type'], b['other_config'], b['external_ids'])

    print(f"Ready — {len(bridges)} bridge(s) published.", flush=True)

    # Signal dinit that we're ready
    fd_str = os.environ.get("DINIT_DBUS_READY_FD")
    if fd_str:
        try:
            fd = int(fd_str)
            os.write(fd, b"\n")
            os.close(fd)
        except OSError:
            pass

    threading.Event().wait()

if __name__ == "__main__":
    main()

