/// Returns one `HostEntry` per logical group.  The caller publishes each
/// entry as a `MirrorObject`; on refresh the old objects are replaced.
pub async fn gather() -> Vec<HostEntry> {
    tokio::join!(
        gather_memory(),
        gather_loadavg(),
        gather_uptime(),
        gather_cpuinfo(),
        gather_stat(),
        gather_net_dev(),
        gather_net_if_inet(),
        gather_mounts(),
        gather_kernel(),
        gather_vm(),
        gather_diskstats(),
        gather_sys_net(),
    )
    .into_entries()
}

