async fn gather_cpuinfo() -> HostEntry {
    let raw = read_proc("cpuinfo").await;
    // Collect per-core records; each blank-line-separated block is one CPU.
    let mut cpus: Vec<Value> = Vec::new();
    let mut cur = simd_json::owned::Object::new();
    for line in raw.lines() {
        if line.trim().is_empty() {
            if !cur.is_empty() {
                cpus.push(Value::Object(Box::new(std::mem::replace(
                    &mut cur,
                    simd_json::owned::Object::new(),
                ))));
            }
        } else if let Some((k, v)) = line.split_once(':') {
            cur.insert(k.trim().replace(' ', "_").to_lowercase(), num_or_str(v));
        }
    }
    if !cur.is_empty() {
        cpus.push(Value::Object(Box::new(cur)));
    }
    let mut map = simd_json::owned::Object::new();
    map.insert("count".into(), Value::from(cpus.len() as i64));
    map.insert("cpus".into(), Value::Array(cpus));
    HostEntry {
        subpath: "cpuinfo",
        data: Value::Object(Box::new(map)),
    }
}

async fn gather_stat() -> HostEntry {
    let raw = read_proc("stat").await;
    let mut map = simd_json::owned::Object::new();
    let mut cpus: Vec<Value> = Vec::new();
    for line in raw.lines() {
        if line.starts_with("cpu") {
            let parts: Vec<&str> = line.splitn(11, ' ').collect();
            if parts.len() >= 8 {
                let labels = [
                    "user", "nice", "system", "idle", "iowait", "irq", "softirq", "steal",
                ];
                let mut cpu_map = simd_json::owned::Object::new();
                cpu_map.insert("name".into(), Value::from(parts[0].to_string()));
                for (i, label) in labels.iter().enumerate() {
                    if let Some(v) = parts.get(i + 1) {
                        cpu_map.insert((*label).into(), num_or_str(v));
                    }
                }
                cpus.push(Value::Object(Box::new(cpu_map)));
            }
        } else if let Some((k, v)) = line.split_once(' ') {
            map.insert(k.into(), num_or_str(v));
        }
    }
    map.insert("cpu_times".into(), Value::Array(cpus));
    HostEntry {
        subpath: "stat",
        data: Value::Object(Box::new(map)),
    }
}

