                "tx_errs",
                "tx_drop",
                "tx_fifo",
                "tx_colls",
                "tx_carrier",
                "tx_compressed",
            ];
            let mut m = simd_json::owned::Object::new();
            m.insert("interface".into(), Value::from(iface.trim().to_string()));
            for (i, label) in labels.iter().enumerate() {
                if let Some(v) = parts.get(i) {
