    async fn register_in_object_manager(&self, path: &str, data: &Value) {
        let op = match OwnedObjectPath::try_from(path.to_string()) {
            Ok(p) => p,
            Err(e) => {
                tracing::warn!("register_in_object_manager: invalid path {path}: {e}");
                return;
            }
        };

