fn is_service_already(error: &ZbusError) -> bool {
    matches!(
        error,
        ZbusError::MethodError(name, _, _)
            if name.as_str() == "org.chimera.dinit.Error.ServiceAlready"
    )
}

fn map_service_state(current_state: &str) -> String {
    match current_state {
